#include "spacepdhcg/cuda/gtoc12_conic_c_api.h"
#include <cuda_runtime.h>
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

namespace {
void require(bool ok, const char* message) {
    if (!ok) { std::fprintf(stderr, "FAIL: %s\n", message); std::exit(1); }
}
void check(cudaError_t status) { require(status == cudaSuccess, cudaGetErrorString(status)); }
template<class T> struct Device {
    T* data{};
    explicit Device(size_t n) { check(cudaMalloc(&data, n*sizeof(T))); }
    ~Device() { cudaFree(data); }
};
}
int main() {
    for (int hold : {0, 1}) for (int k : {3, 257}) {
        const int n = k+1;
        std::vector<double> times(n), states(7*n), controls(4*n), fuel(n, 0.002);
        for (int i = 0; i < n; ++i) {
            times[i] = 0.003*i;
            states[7*i] = 2.7; states[7*i+4] = 0.61; states[7*i+6] = 0.95;
            controls[4*i] = 0.03; controls[4*i+3] = 0.04;
        }
        const double boundary[]{2.7,0,0,0,0.61,0,2.7,0,0,0,0.61,0};
        spacepdhcg_gtoc12_conic* w{};
        require(spacepdhcg_gtoc12_conic_create(k, hold, 1, 1, 0.15, 0.03,
            times.data(), boundary, fuel.data(), &w) == 0, "create");
        spacepdhcg_gtoc12_conic_dimensions d{};
        require(spacepdhcg_gtoc12_conic_get_dimensions(w, &d) == 0, "dimensions");
        require(d.variables == 25*n-8 && d.equalities == 7*k+13+(hold ? 0 : 4)
            && d.inequalities == 26*n+14*k && d.soc_count == n+2, "independent layout counts");
        spacepdhcg_gtoc12_conic_device_outputs out{};
        require(spacepdhcg_gtoc12_conic_outputs(w, &out) == 0, "device outputs");
        const size_t count = d.a_nonzeros+d.rows+d.variables+d.p_nonzeros;
        std::vector<double> actual(count), expected(count);
        std::vector<int> ao(d.variables+1), ai(d.a_nonzeros), po(d.variables+1), pi(d.p_nonzeros);
        require(spacepdhcg_gtoc12_conic_copy_topology_host(w, ao.data(), ai.data(), po.data(), pi.data()) == 0, "topology");
        require(ao.back() == d.a_nonzeros && po.back() == d.p_nonzeros, "CSC terminal offsets");
        for (int col = 0; col < d.variables; ++col)
            for (int i = ao[col]+1; i < ao[col+1]; ++i) require(ai[i] > ai[i-1], "strict sorted unique CSC");
        Device<double> ds(states.size()), du(controls.size());
        Device<spacepdhcg_gtoc12_conic_parameters> dp(1);
        Device<int> steps(1), enabled(1);
        cudaStream_t stream{}; check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
        // First-ever invalid scheduling must not read uninitialised dynamics,
        // states, controls or parameters, or replace retained output values.
        int step_count=0,run=1;
        check(cudaMemsetAsync(const_cast<double*>(out.a),0,count*sizeof(double),stream));
        check(cudaMemcpyAsync(steps.data,&step_count,sizeof(int),cudaMemcpyHostToDevice,stream));
        check(cudaMemcpyAsync(enabled.data,&run,sizeof(int),cudaMemcpyHostToDevice,stream));
        require(spacepdhcg_gtoc12_conic_launch_controlled_device(w,ds.data,du.data,dp.data,
            steps.data,enabled.data,stream)==0,"first invalid scheduling enqueued");
        int first_invalid=0;
        check(cudaMemcpyAsync(&first_invalid,out.invalid,sizeof(int),cudaMemcpyDeviceToHost,stream));
        check(cudaMemcpyAsync(actual.data(),out.a,count*sizeof(double),cudaMemcpyDeviceToHost,stream));
        check(cudaStreamSynchronize(stream));
        require(first_invalid==1 && std::all_of(actual.begin(),actual.end(),[](double v){return v==0;}),
            "first invalid scheduling preserves output without stale reads");
        cudaGraph_t graph{}; cudaGraphExec_t executable{};
        check(cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal));
        require(spacepdhcg_gtoc12_conic_launch_device(w, ds.data, du.data, dp.data, 8, stream) == 0,
            "device dynamics plus assembly capture without host sync or allocation");
        check(cudaStreamEndCapture(stream, &graph));
        check(cudaGraphInstantiate(&executable, graph, nullptr, nullptr, 0));
        for (int repeat = 0; repeat < 12; ++repeat) {
            spacepdhcg_gtoc12_conic_parameters p{0.1/(repeat+1),0.2,13.0+repeat,0.3,0.05,0.03,repeat*0.001};
            for (int i = 0; i < n; ++i) { controls[4*i] += 0.0001; states[7*i] += 0.00001; }
            check(cudaMemcpyAsync(ds.data, states.data(), states.size()*sizeof(double), cudaMemcpyHostToDevice, stream));
            check(cudaMemcpyAsync(du.data, controls.data(), controls.size()*sizeof(double), cudaMemcpyHostToDevice, stream));
            check(cudaMemcpyAsync(dp.data, &p, sizeof(p), cudaMemcpyHostToDevice, stream));
            check(cudaGraphLaunch(executable, stream));
            int invalid = -1;
            check(cudaMemcpyAsync(actual.data(), out.a, count*sizeof(double), cudaMemcpyDeviceToHost, stream));
            check(cudaMemcpyAsync(&invalid, out.invalid, sizeof(int), cudaMemcpyDeviceToHost, stream));
            check(cudaStreamSynchronize(stream));
            require(invalid == 0, "valid graph outputs");
            require(spacepdhcg_gtoc12_conic_evaluate_host(w, states.data(), controls.data(), &p, 8, expected.data()) == 0,
                "host bridge");
            for (size_t i = 0; i < count; ++i) require(actual[i] == expected[i], "graph/bridge identical values");
            // Independent objective and Hessian terms, including zero smoothness.
            const double* q = actual.data()+d.a_nonzeros+d.rows;
            const double* pv = q+d.variables;
            for (int node = 0; node < n; ++node) require(q[7*n+4*node+3] == fuel[node], "fuel weights");
            for (int i = 11*n+7*k; i < 11*n+14*k; ++i) require(q[i] == p.virtual_weight, "virtual penalty");
            for (int col = 0; col < d.variables; ++col) for (int i = po[col]; i < po[col+1]; ++i) {
                const int node = (col-7*n)/4;
                const double factor = pi[i] != col ? -2.0 : (node == 0 || node == k ? 2.0 : 4.0);
                require(pv[i] == factor*p.smoothness_weight, "smoothness Hessian");
            }
        }
        spacepdhcg_gtoc12_conic_parameters bad{0.1,0.2,13.0,0.3,0.05,0.03,-1.0};
        check(cudaMemcpyAsync(dp.data, &bad, sizeof(bad), cudaMemcpyHostToDevice, stream));
        check(cudaGraphLaunch(executable, stream));
        int invalid = 0;
        check(cudaMemcpyAsync(&invalid, out.invalid, sizeof(int), cudaMemcpyDeviceToHost, stream));
        check(cudaStreamSynchronize(stream)); require(invalid == 1, "invalid graph parameter surfaced");
        bad.smoothness_weight = 0.0;
        require(spacepdhcg_gtoc12_conic_evaluate_host(w, states.data(), controls.data(), &bad, 8, expected.data()) == 0, "invalid flag reset");
        require(spacepdhcg_gtoc12_conic_launch_device(w, ds.data, du.data, dp.data, 0, stream) == 1, "bad substeps");
        check(cudaGraphExecDestroy(executable)); check(cudaGraphDestroy(graph));
        check(cudaMemcpyAsync(dp.data,&bad,sizeof(bad),cudaMemcpyHostToDevice,stream));
        check(cudaStreamBeginCapture(stream,cudaStreamCaptureModeThreadLocal));
        require(spacepdhcg_gtoc12_conic_launch_controlled_device(w,ds.data,du.data,dp.data,
            steps.data,enabled.data,stream)==0,"controlled conic capture");
        check(cudaStreamEndCapture(stream,&graph));
        check(cudaGraphInstantiate(&executable,graph,nullptr,nullptr,0));
        for (auto config : std::initializer_list<std::pair<int,int>>{{1,1},{8,1},{16,-1},{0,1},{-3,1},{0,0},{8,1}}) {
            step_count=config.first;run=config.second;
            if (run && step_count>0) {
                check(cudaStreamSynchronize(stream));
                require(spacepdhcg_gtoc12_conic_evaluate_host(w,states.data(),controls.data(),&bad,
                    step_count,expected.data())==0,"fixed conic reference");
            } else {
                check(cudaMemcpyAsync(expected.data(),out.a,count*sizeof(double),cudaMemcpyDeviceToHost,stream));
            }
            int previous_invalid=0;
            check(cudaMemcpyAsync(&previous_invalid,out.invalid,sizeof(int),cudaMemcpyDeviceToHost,stream));
            check(cudaMemcpyAsync(steps.data,&step_count,sizeof(int),cudaMemcpyHostToDevice,stream));
            check(cudaMemcpyAsync(enabled.data,&run,sizeof(int),cudaMemcpyHostToDevice,stream));
            check(cudaGraphLaunch(executable,stream));
            check(cudaMemcpyAsync(actual.data(),out.a,count*sizeof(double),cudaMemcpyDeviceToHost,stream));
            check(cudaMemcpyAsync(&invalid,out.invalid,sizeof(int),cudaMemcpyDeviceToHost,stream));
            check(cudaStreamSynchronize(stream));
            require(std::memcmp(actual.data(),expected.data(),count*sizeof(double))==0,"controlled conic parity/preservation");
            require(invalid==(run ? int(step_count<1) : previous_invalid),"controlled conic invalid flag");
        }
        check(cudaGraphExecDestroy(executable)); check(cudaGraphDestroy(graph));
        check(cudaStreamDestroy(stream)); spacepdhcg_gtoc12_conic_destroy(w);
        spacepdhcg_gtoc12_conic* rejected{};
        require(spacepdhcg_gtoc12_conic_create(k, hold, 2, 0, 0.15, 0.03,
            times.data(), boundary, fuel.data(), &rejected) == 1 && !rejected, "invalid topology rejected");
    }
    std::puts("GTOC12 conic: 48 input replays, 28 controlled replays, 4 first-invalid cases, topology/objective/Hessian PASS");
}

cpp/cuda/tests/gtoc12_qoco_guard_test.cu.text:
#include "spacepdhcg/cuda/gtoc12_qoco_c_api.h"
#include <cuda_runtime.h>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <initializer_list>

#define REQUIRE(x) do { if (!(x)) { std::fprintf(stderr,"line %d: %s\n",__LINE__,#x); std::exit(1); } } while (0)
#define CUDA(x) REQUIRE((x)==cudaSuccess)

struct Observed { int calls, qualified, status, iterations; };
__global__ void set_steps(int* output,int value) { *output=value; }
__global__ void consume(const spacepdhcg_gtoc12_qoco_report* report, Observed* result) {
    ++result->calls;
    result->qualified=report->qualified; result->status=report->qoco_status;
    result->iterations=report->iterations;
}
int consumer(void* opaque, const spacepdhcg_gtoc12_qoco_report* report, const double*, void* stream) {
    consume<<<1,1,0,static_cast<cudaStream_t>(stream)>>>(report,static_cast<Observed*>(opaque));
    return cudaGetLastError()==cudaSuccess ? 0 : 1;
}

int main() {
    if (!std::getenv("SPACEPDHCG_QOCO_LIBRARY")) { std::puts("SKIP: prepared QOCO required"); return 0; }
    double times[4]{0,.003,.006,.009}, states[28]{}, controls[16]{}, boundary[12]{};
    double weights[4]{.003,.003,.003,0};
    const double omega=std::pow(2.7,-1.5);
    for (int k=0;k<4;++k) {
        states[7*k]=2.7*std::cos(omega*times[k]); states[7*k+1]=2.7*std::sin(omega*times[k]);
        states[7*k+3]=-2.7*omega*std::sin(omega*times[k]);
        states[7*k+4]=2.7*omega*std::cos(omega*times[k]); states[7*k+6]=1;
    }
    for (int j=0;j<6;++j) { boundary[j]=states[j]; boundary[6+j]=states[21+j]; }
    setenv("SPACEPDHCG_TEST_QOCO_IPM_GRAPH","1",1);
    setenv("SPACEPDHCG_TEST_QOCO_NATIVE_REPLAY","1",1);
    setenv("SPACEPDHCG_TEST_QOCO_DEVICE_VALIDATION","1",1);
    setenv("SPACEPDHCG_TEST_GTOC12_DEVICE_ASSEMBLY_VALIDATION","1",1);
    for (bool controlled:{false,true}) for (int mode=0;mode<3;++mode) {
        setenv("SPACEPDHCG_TEST_QOCO_NATIVE_NUMERIC_REPLAY",mode==1 ? "0" : "1",1);
        setenv("SPACEPDHCG_TEST_QOCO_GPU_CONVERSION_COMPARE",mode==2 ? "1" : "0",1);
        cudaStream_t stream{}; CUDA(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));
        double *ds{},*du{}; spacepdhcg_gtoc12_conic_parameters* dp{}; Observed* observed{};
        int* device_steps{}; int substeps=8;
        CUDA(cudaMalloc(&device_steps,sizeof(int)));
        CUDA(cudaMalloc(&ds,sizeof(states))); CUDA(cudaMalloc(&du,sizeof(controls)));
        CUDA(cudaMalloc(&dp,sizeof(*dp))); CUDA(cudaMalloc(&observed,sizeof(*observed)));
        spacepdhcg_gtoc12_qoco* w{};
        REQUIRE(spacepdhcg_gtoc12_qoco_create(3,0,1,1,.04047160536675379,.030730022327172587,
            times,boundary,weights,1e-9,0,&w)==0);
        const spacepdhcg_gtoc12_conic_parameters valid{.1,.3,13,.3,.05,.02,.001};
        auto params=valid;
        spacepdhcg_gtoc12_qoco_report report{}; Observed result{}; int consumed{};
        if (controlled) REQUIRE(spacepdhcg_gtoc12_qoco_solve_controlled_device_with_consumer(
            w,ds,du,dp,nullptr,stream,&report,consumer,observed,&consumed)==1 && !consumed && !report.qualified);
        const auto solve=[&] {
            CUDA(cudaMemcpyAsync(ds,states,sizeof(states),cudaMemcpyHostToDevice,stream));
            CUDA(cudaMemcpyAsync(du,controls,sizeof(controls),cudaMemcpyHostToDevice,stream));
            CUDA(cudaMemcpyAsync(dp,&params,sizeof(params),cudaMemcpyHostToDevice,stream));
            CUDA(cudaMemsetAsync(observed,0,sizeof(*observed),stream));
            set_steps<<<1,1,0,stream>>>(device_steps,substeps);
            const int code=controlled
                ? spacepdhcg_gtoc12_qoco_solve_controlled_device_with_consumer(w,ds,du,dp,device_steps,stream,
                &report,consumer,observed,&consumed)
                : spacepdhcg_gtoc12_qoco_solve_device_with_consumer(w,ds,du,dp,8,stream,
                &report,consumer,observed,&consumed);
            CUDA(cudaMemcpyAsync(&result,observed,sizeof(result),cudaMemcpyDeviceToHost,stream));
            CUDA(cudaStreamSynchronize(stream));
            return code;
        };
        if (controlled) substeps=0; else params.trust_state=-.1;
        REQUIRE(solve()==3 && !consumed && result.calls==0 && !report.qualified);
        params=valid;substeps=8;
        for (int bad=0;bad<(controlled ? 6 : 4);++bad) {
            for (int prime=0;prime<3;++prime) {
                substeps=controlled && prime==1 ? 16 : 8;
                REQUIRE(solve()==0 && consumed==1 && result.calls==1 && result.qualified==1);
                REQUIRE(report.primal_residual<=1e-9 && report.dual_residual<=1e-9 && report.relative_gap<=1e-9);
            }
            const auto completed=report.solves;
            if (bad==0) params.trust_state=-.1;
            if (bad==1) params.minimum_mass=0;
            if (bad==2) states[6]=-1;
            if (bad==3) controls[4]=std::numeric_limits<double>::quiet_NaN();
            if (bad==4) substeps=0;
            if (bad==5) substeps=-7;
            REQUIRE(solve()==3 && !report.qualified && report.iterations==0 && report.solves==completed);
            REQUIRE(std::isinf(report.primal_residual) && std::isinf(report.dual_residual));
            if (mode==0) REQUIRE(consumed==1 && result.calls==1 && result.qualified==0
                && result.status==3 && result.iterations==0);
            else REQUIRE(consumed==0 && result.calls==0);
            params=valid; states[6]=1; controls[4]=0;substeps=8;
        }
        REQUIRE(solve()==0 && result.qualified==1);
        spacepdhcg_gtoc12_qoco_destroy(w);
        CUDA(cudaFree(ds)); CUDA(cudaFree(du)); CUDA(cudaFree(dp)); CUDA(cudaFree(observed));
        CUDA(cudaFree(device_steps));
        CUDA(cudaStreamDestroy(stream));
    }
    std::puts("GTOC12 assembly guard: 10 queued GPU-consumer rejections, 20 fallback rejections, device step changes, first-invalid and qualified recovery PASS");
}

